insert into public.questions (id, category, text, code, language, options, correct_index, explanation, difficulty) values
  ('bug-01', 'spot-the-bug', 'What''s the bug?', 'const spooky = true;
spooky = false;', 'javascript', '["Missing semicolon","Reassigning a const variable","Incorrect Boolean syntax","No bug"]'::jsonb, 1, 'A `const` binding cannot be reassigned. This throws "TypeError: Assignment to constant variable."', 'easy'),
  ('bug-02', 'spot-the-bug', 'This loop crashes on its last lap. Why?', 'const nums = [1, 2, 3];
for (let i = 0; i <= nums.length; i++) {
  console.log(nums[i].toFixed(1));
}', 'javascript', '["toFixed does not exist on numbers","Off-by-one: `<=` reads past the end, so nums[3] is undefined","`let` cannot be used in loops","nums should be declared with var"]'::jsonb, 1, 'Valid indexes are 0 to length - 1. `nums[3]` is undefined, and `undefined.toFixed()` throws a TypeError. Use `<`.', 'easy'),
  ('bug-03', 'spot-the-bug', 'Which part of this markup is invalid?', '<ul>
  <li>Candy</li>
  <div>Pumpkin</div>
  <li>Cobwebs</li>
</ul>', 'html', '["The ul is missing a closing tag","A div is not allowed as a direct child of ul","Every li must contain a link","No bug"]'::jsonb, 1, 'The only permitted direct children of `<ul>` are `<li>` (plus script-supporting elements). Wrap the div inside an li instead.', 'medium'),
  ('bug-04', 'spot-the-bug', 'The ghost stays solid. What went wrong?', '.ghost {
  color: white
  opacity: 0.5;
}', 'css', '["opacity cannot be 0.5","The class selector needs a # prefix","Missing semicolon: the browser drops both declarations","\"white\" is not a valid colour"]'::jsonb, 2, 'Without the semicolon the parser reads `white opacity: 0.5` as one invalid value and discards the whole declaration, so neither colour nor opacity is applied.', 'medium'),
  ('bug-05', 'spot-the-bug', 'Everyone can enter the secret lair! Why?', 'if (user.role = ''admin'') {
  showSecretLair();
}', 'javascript', '["The assignment `=` should be a comparison `===`","if statements need an else branch","showSecretLair must be async","''admin'' must use double quotes"]'::jsonb, 0, '`user.role = ''admin''` assigns the string (which is truthy) and overwrites the role. Use `===` to compare.', 'easy'),
  ('bug-06', 'spot-the-bug', 'The counter never goes up. What is the bug?', '<script setup>
import { ref } from ''vue''
const count = ref(0)
function boo() {
  count++
}
</script>', 'vue', '["ref must be imported from vue/ref","script setup cannot declare functions","No bug","Forgot `.value`: it should be `count.value++`"]'::jsonb, 3, 'Refs are objects; inside script you read and write them through `.value`. (Templates unwrap them automatically.)', 'medium'),
  ('bug-07', 'spot-the-bug', 'Why does `res.json` blow up?', 'async function loadCandy() {
  const res = fetch(''/api/candy'');
  const data = await res.json();
  return data;
}', 'javascript', '["json() is not a Response method","fetch is missing `await`, so res is a Promise","async functions cannot call fetch","It needs XMLHttpRequest instead"]'::jsonb, 1, '`fetch()` returns a Promise. Without `await`, `res` is that Promise and has no `.json()` method yet.', 'easy'),
  ('out-01', 'cursed-output', 'What does this print?', 'console.log(typeof null);', 'javascript', '["null","undefined","object","boolean"]'::jsonb, 2, 'A famous 1995 quirk: `typeof null` is "object". It has never been fixed because too much code relies on it.', 'easy'),
  ('out-02', 'cursed-output', 'Maths is haunted. What prints?', 'console.log(0.1 + 0.2 === 0.3);', 'javascript', '["true","false","NaN","undefined"]'::jsonb, 1, 'Floating-point numbers cannot represent 0.1 and 0.2 exactly. The sum is 0.30000000000000004.', 'easy'),
  ('out-03', 'cursed-output', 'What does this print?', 'console.log([] + {});', 'javascript', '["0","NaN","[object Object]","undefined"]'::jsonb, 2, 'Both operands are converted to strings: `[]` becomes "" and `{}` becomes "[object Object]".', 'medium'),
  ('out-04', 'cursed-output', 'Subtraction vs. addition. What prints?', 'console.log(''5'' - 2, ''5'' + 2);', 'javascript', '["3 7","3 52","52 3","NaN 52"]'::jsonb, 1, '`-` forces numeric conversion (5 - 2 = 3), while `+` with a string concatenates ("5" + "2" = "52").', 'easy'),
  ('out-05', 'cursed-output', 'What does this cursed one-liner print?', 'console.log([1, 2, 3].map(parseInt));', 'javascript', '["[1, 2, 3]","[1, NaN, NaN]","[NaN, NaN, NaN]","[1, 2, NaN]"]'::jsonb, 1, 'map passes (value, index), so it runs parseInt("2", 1) and parseInt("3", 2). Radix 1 is invalid and "3" is not a binary digit, so both are NaN.', 'hard'),
  ('out-06', 'cursed-output', 'What type is "Not a Number"?', 'console.log(typeof NaN);', 'javascript', '["NaN","undefined","number","object"]'::jsonb, 2, 'NaN is a special value of the number type. The irony is free of charge.', 'easy'),
  ('out-07', 'cursed-output', 'Three ghosts, three timeouts. What prints?', 'for (var i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 0);
}', 'javascript', '["0 1 2","3 3 3","2 2 2","undefined undefined undefined"]'::jsonb, 1, '`var` is function-scoped, so all callbacks share one `i`, which is 3 by the time they run. With `let` you would get 0 1 2.', 'medium'),
  ('bluff-01', 'bug-or-bluff', 'CSS can select an element based on whether it contains another element.', null, null, '["Bug — False","Bluff — True"]'::jsonb, 1, 'True! The `:has()` relational pseudo-class is the long-awaited "parent selector". Example: `card:has(img)`.', 'easy'),
  ('bluff-02', 'bug-or-bluff', 'In JavaScript, `NaN === NaN` evaluates to true.', null, null, '["Bug — False","Bluff — True"]'::jsonb, 0, 'False. NaN is the only value not equal to itself. Use `Number.isNaN(x)` to check for it.', 'easy'),
  ('bluff-03', 'bug-or-bluff', '`[10, 9, 1].sort()` returns `[1, 9, 10]`.', null, null, '["Bug — False","Bluff — True"]'::jsonb, 0, 'False. Without a comparator, sort() compares items as strings, giving `[1, 10, 9]`. Use `.sort((a, b) => a - b)`.', 'medium'),
  ('bluff-04', 'bug-or-bluff', 'HTML has a native `<dialog>` element that can open a modal with no library at all.', null, null, '["Bug — False","Bluff — True"]'::jsonb, 1, 'True! Call `dialog.showModal()` and you get a focus trap, backdrop, and Escape-to-close for free.', 'easy'),
  ('bluff-05', 'bug-or-bluff', 'The CSS `z-index` property works on every element, even ones with `position: static` (and no flex or grid parent).', null, null, '["Bug — False","Bluff — True"]'::jsonb, 0, 'False. z-index only applies to positioned elements and to flex/grid items. Plain static boxes ignore it.', 'medium'),
  ('bluff-06', 'bug-or-bluff', 'Declaring an object with `const` makes it completely immutable.', null, null, '["Bug — False","Bluff — True"]'::jsonb, 0, 'False. `const` stops reassignment of the variable, but you can still change properties. Use `Object.freeze()` for shallow immutability.', 'easy'),
  ('bluff-07', 'bug-or-bluff', 'In JavaScript, `0 == ''0''` is true and `0 == []` is true, but `''0'' == []` is false.', null, null, '["Bug — False","Bluff — True"]'::jsonb, 1, 'True! Loose equality coerces: `[]` becomes "" then 0, so 0 == []. But "0" == "" compares two strings and is false. Just use `===`.', 'hard'),
  ('ui-01', 'ui-monster', 'A screen reader announces just "button". What is the monster?', '<button class="close">
  <svg viewBox="0 0 24 24">…</svg>
</button>', 'html', '["The icon-only button has no accessible name","The SVG is too small","A button should be a div","It needs tabindex=\"5\""]'::jsonb, 0, 'Icon-only buttons need a name: add `aria-label="Close"` (and `aria-hidden="true"` on the SVG) or visually hidden text.', 'easy'),
  ('ui-02', 'ui-monster', 'Which accessibility monster lurks in this field?', '<input type="email" placeholder="Your email">', 'html', '["type=\"email\" is deprecated","The input has no programmatic label; a placeholder is not a label","Inputs must be wrapped in a div","Placeholders can only hold numbers"]'::jsonb, 1, 'Placeholders disappear while typing and are not reliably announced. Use a visible `<label for>` associated with the input.', 'easy'),
  ('ui-03', 'ui-monster', 'Keyboard users cannot cast the spell. Why?', '<div class="btn" onclick="castSpell()">
