  ('ui-05', 'ui-monster', 'Hint text is "grey on white" (#9a9a9a on #ffffff). What is the monster?', '.hint {
  color: #9a9a9a;
  background: #ffffff;
}', 'css', '["Hex colours must be uppercase","Contrast is about 2.8:1, below the 4.5:1 WCAG AA minimum for normal text","Grey is not allowed on white","Text must always be black"]'::jsonb, 1, 'WCAG AA requires at least 4.5:1 for normal text (3:1 for large text). #767676 is the lightest grey that passes on white.', 'medium'),
  ('ui-06', 'ui-monster', 'The only error indicator is a red border. What is the monster?', '.field.error {
